function rejectedFixture(mutation=null){
 const f=fixture(mutation);
 f.children[6].payload.input=`text(await tools.exec_command(${JSON.stringify({cmd:"cat '/missing/facts.md'",login:false,max_output_tokens:16000})}));`;
 f.children[7].payload.output=output({exit_code:1,output:'cat: /missing/facts.md: No such file or directory\n'});
 f.children.splice(8,2,
  row('response_item',{type:'function_call',namespace:'collaboration',name:'send_message',call_id:'report',arguments:JSON.stringify({target:'/root',message:'Facts read failed.'})},14),
  row('response_item',{type:'function_call_output',call_id:'report',output:''},15),
  row('response_item',{type:'function_call',namespace:'collaboration',name:'wait_agent',call_id:'wait',arguments:'{"timeout_ms":10000}'},16),
  row('response_item',{type:'function_call_output',call_id:'wait',output:'{"timed_out":true}'},17),
  row('response_item',{type:'agent_message',author:'/root',recipient:'/root/gui',content:[{type:'input_text',text:'Stop; report the prerequisite failure.'}]},18));
 f.children.at(-2).payload.content[0].text='Facts unavailable. No Dragon calls; product verdict UNGRADED.';
 f.children.at(-2).timestamp=row('unused',{},19).timestamp;f.children.at(-1).timestamp=row('unused',{},20).timestamp;
 f.save();return f;
}
const deniedText='Script error:\nTool call blocked by PreToolUse hook: DRAGON_REQUEST_INVALID. Tool: mcp__Dragon_Browser__dragon_rpc';
function hostDeniedFixture(mutation=null){
 const f=fixture(mutation),request={op:'do',sessionId:'session',nonce:'nonce',browserInstanceId:'browser',tabId:2,steps:[{read:'return location.href',as:'page'}]};
 f.children[8]=row('response_item',{type:'custom_tool_call',name:'exec',call_id:'denied',input:`text(await tools.mcp__Dragon_Browser__dragon_rpc(${JSON.stringify(request)}));\n`},14);
 f.children[9]=row('response_item',{type:'custom_tool_call_output',call_id:'denied',output:[{type:'input_text',text:'Script failed\nWall time 0.3 seconds\nOutput:\n'},{type:'input_text',text:deniedText}]},15);
 f.children[9].metadata={client_authored:false};f.children[10].payload.content[0].text='Request rejected by host. No Dragon action; UNGRADED.';
 f.save();return f;
}
function runFixtureScript(f,script){
 const runner=join(f.dir,'rejected-attempt-check.mjs');
 writeFileSync(runner,`import assert from 'node:assert/strict';import{readFileSync,writeFileSync,appendFileSync,existsSync}from'node:fs';import{join}from'node:path';import{createHash}from'node:crypto';import{closeNativeAttempt,verifyNativeAttemptClosure,prepareNativeRole}from${JSON.stringify(url(f.module))};const hash=x=>createHash('sha256').update(x).digest('hex');const f=${JSON.stringify({runDir:f.run,intentPath:f.intentPath,prepareSource:f.evidence.prepare_source,parentSource:f.evidence.parent_source,childSourcePath:f.evidence.child_source_path,factsPath:f.intent.facts_path,policyPath:f.policyPath,home:f.home})};${script}`);
 return spawnSync(process.execPath,[runner],{encoding:'utf8',env:{...process.env,HOME:f.home}});
}
test('original host-denied malformed RPC closes without attestation and preserves retry chain',()=>{
 const f=hostDeniedFixture(),before=hash(readFileSync(f.evidence.child_source_path));
 const run=runFixtureScript(f,`
 const closed=await closeNativeAttempt(f),intent=JSON.parse(readFileSync(f.intentPath));
 assert.equal(closed.terminal.kind,'rejected_execution');assert.equal(closed.terminal.host_denied_request.call_id,'denied');
 assert.equal(closed.terminal.host_denied_request.request_line,9);assert.equal(closed.terminal.host_denied_request.output_line,10);
 for(const error of ['TOOL_FAILED','NATIVE_GUI_TRAJECTORY:NATIVE_GUI_REQUEST_UNKNOWN','NATIVE_GUI_TRAJECTORY:NATIVE_GUI_CAPABILITY_UNAPPROVED','NATIVE_GUI_TRAJECTORY:NATIVE_GUI_SESSION_DRIFT','NATIVE_GUI_TRAJECTORY:NATIVE_GUI_OPERATION_FAILED','NATIVE_GUI_TRAJECTORY:NATIVE_GUI_STATIC_IMAGE_REQUIRED'])assert.ok(closed.parser_errors.includes(error),error);
 assert.equal(verifyNativeAttemptClosure({runDir:f.runDir,intent}),true);assert.equal(existsSync(join(f.runDir,'role-bindings/executor_gui.json')),false);
 const prompt=join(f.runDir,'retry-prompt.md');writeFileSync(prompt,'Continue scoped test.');
 const next=await prepareNativeRole({runDir:f.runDir,role:'executor_gui',prompt,factsPath:f.factsPath,guiPolicyPath:f.policyPath,dispatchAttemptId:'denied_retry_0002',dispatchAttemptSeq:2,caseId:'C1'});
 assert.equal(next.dispatch_previous_sha256,hash(readFileSync(join(f.runDir,'native-dispatch/executor_gui/attempt-1/closed.json'))));assert.equal(next.dispatch_previous_intent_sha256,hash(readFileSync(f.intentPath)));
 const packet=readFileSync(next.context_packet_path,'utf8');assert.ok(packet.includes('Dragon RPC envelope uses method and nested params (for example {"method":"do","params":{...}}'));assert.ok(packet.includes('do not use op or top-level session fields'));assert.ok(packet.includes('Method must be one declared by the locked policy'));
 const context=JSON.parse(readFileSync(join(f.runDir,'fixture-roster.json'))).roles[0].context.map(x=>readFileSync(join(${JSON.stringify(root)},x.path),'utf8')).join('\\n\\n'),prefix=next.spawn.message.split('\\n')[0]+'\\n'+context+'\\n\\n';assert.equal(hash(packet.slice(prefix.length)),next.prompt_sha256);
 console.log('HOST_DENIAL_CLOSED_AND_CHAINED');`);
 assert.equal(run.status,0,run.stderr);assert.match(run.stdout,/HOST_DENIAL_CLOSED_AND_CHAINED/);assert.equal(hash(readFileSync(f.evidence.child_source_path)),before);
 const strict=f.check();assert.equal(strict.status,3);assert.match(strict.stderr,/NATIVE_RUNTIME_UNATTESTED/);
});
test('host-denied closure rejects prose, fake or unmatched outputs, session drift and missing facts',()=>{
 for(const defect of ['prose','client-authored','missing-host-flag','mismatched-output','duplicate-output','different-tool','executed','session-drift','valid-envelope','facts','running','identity','prepare-hash']){
  const f=hostDeniedFixture();
  if(defect==='prose'){f.children[10].payload.content[0].text=deniedText;f.children[9].payload.output[1].text='Script error:\nExecution failed';}
  if(defect==='client-authored')f.children[9].metadata.client_authored=true;
  if(defect==='missing-host-flag')delete f.children[9].metadata;
  if(defect==='mismatched-output')f.children[9].payload.call_id='other';
  if(defect==='duplicate-output')f.children.splice(10,0,structuredClone(f.children[9]));
  if(defect==='different-tool')f.children[9].payload.output[1].text=deniedText.replace('dragon_rpc','other_rpc');
  if(defect==='executed')f.children[9].payload.output=output({ok:true,result:{}});
  if(defect==='session-drift')f.children[8].payload.input=f.children[8].payload.input.replace('"sessionId":"session"','"sessionId":"other"');
  if(defect==='valid-envelope'){f.children[8].payload.input='text(await tools.mcp__Dragon_Browser__dragon_rpc('+JSON.stringify({method:'screenshot',params:{sessionId:'other',nonce:'nonce',browserInstanceId:'browser',tabId:2,toFile:join(f.run,'shot.png')}})+'));';f.children[9].payload.output=output({ok:false,error:'session mismatch'});}
  if(defect==='facts')f.children[7].payload.output=output({exit_code:0,output:'wrong facts'});
  if(defect==='running')f.children.pop();
  if(defect==='identity')f.children[0].payload.source.subagent.thread_spawn.parent_thread_id='other';
  if(defect==='prepare-hash')f.evidence.prepare_source.sha256='0'.repeat(64);
  f.save();const run=runFixtureScript(f,`await assert.rejects(closeNativeAttempt(f));assert.equal(existsSync(join(f.runDir,'native-dispatch/executor_gui/attempt-1/closed.json')),false);console.log('INVALID_HOST_DENIAL_REJECTED');`);
  assert.equal(run.status,0,defect+': '+run.stderr);assert.match(run.stdout,/INVALID_HOST_DENIAL_REJECTED/);
 }
 const anchor='if(!allowExecutionFailure&&(!parsed.provenance_verified||parsed.errors?.length))',f=hostDeniedFixture([anchor,"parsed.errors.push('UNKNOWN_FUTURE_FAILURE');"+anchor]);
 const run=runFixtureScript(f,`await assert.rejects(closeNativeAttempt(f),e=>e.code==='NATIVE_CLOSURE_EVIDENCE');console.log('UNKNOWN_DENIAL_ERROR_REJECTED');`);assert.equal(run.status,0,run.stderr);
});
test('host denial receipt revalidates original request/output hashes and complete source',()=>{
 for(const defect of ['request-proof','output-proof','original-request','original-output']){
  const f=hostDeniedFixture(),run=runFixtureScript(f,`const receipt=await closeNativeAttempt(f),intent=JSON.parse(readFileSync(f.intentPath)),path=join(f.runDir,'native-dispatch/executor_gui/attempt-1/closed.json');
   if(${JSON.stringify(defect)}.endsWith('proof')){receipt.terminal.host_denied_request[${JSON.stringify(defect)}==='request-proof'?'request_sha256':'output_sha256']='0'.repeat(64);writeFileSync(path,JSON.stringify(receipt));}
   else{const rows=readFileSync(f.childSourcePath,'utf8').trimEnd().split('\\n').map(JSON.parse);if(${JSON.stringify(defect)}==='original-request')rows[8].payload.input+=' ';else rows[9].payload.output[0].text='Script failed\\nWall time 0.4 seconds\\nOutput:\\n';writeFileSync(f.childSourcePath,rows.map(JSON.stringify).join('\\n')+'\\n');}
   assert.equal(verifyNativeAttemptClosure({runDir:f.runDir,intent}),false);console.log('HOST_DENIAL_DRIFT_REJECTED');`);
  assert.equal(run.status,0,defect+': '+run.stderr);assert.match(run.stdout,/HOST_DENIAL_DRIFT_REJECTED/);
 }
});
